INSERT INTO `activity_details` VALUES ('00000000-0000-4000-8000-000000000302','10000000-0000-4000-8000-000000000022','school_only','Kỹ thuật','Kỹ thuật','Thực hành Python qua các bài toán ứng dụng gần gũi.','Phòng máy thực hành, hướng dẫn từng bước và phần trình bày sản phẩm cuối buổi.','[\"Lập trình theo nhóm\", \"Sửa lỗi chương trình\", \"Trình bày sản phẩm\"]','[\"Python\", \"Tư duy logic\", \"Làm việc nhóm\"]','[\"Đang theo học tại TalentHub Test School\", \"Đăng ký trước thời hạn của hoạt động\"]','[\"Xác nhận giờ trải nghiệm sau check-in\", \"Minh chứng tham gia trên TalentHub\"]','Phòng máy A201','Khuôn viên TalentHub Test School','in_person',NULL,'TalentHub Test School','Liên hệ đơn vị tổ chức',NULL,NULL,'/app/learner/assets/activities/covers/talenthub-python-workshop.webp','Minh họa cho hoạt động Workshop Lập trình Python Ứng dụng',0.00,'VND','Người học đang theo học tại TalentHub Test School','Minh chứng tham gia trên TalentHub','2026-08-25 10:32:44.731024','2026-08-25 10:32:44.731024'),('21000000-04ed-44b5-82fd-0db8f8fd3b05','20000000-0000-4000-8000-000000000050','school_only','Kỹ thuật','Kỹ thuật','Dự án robot cứu hộ đã hoàn thành của học sinh Nguyễn Trãi.','Hoạt động lịch sử lưu lại kết quả thiết kế, thử nghiệm và báo cáo của các đội tham gia.','[\"Thiết kế robot\", \"Thử nghiệm cứu hộ\", \"Báo cáo kết quả\"]','[\"Robotics\", \"Giải quyết vấn đề\", \"Làm việc nhóm\"]','[\"Đang theo học tại THPT Nguyễn Trãi\", \"Đăng ký trước thời hạn của hoạt động\"]','[\"Xác nhận giờ trải nghiệm sau check-in\", \"Minh chứng tham gia trên TalentHub\"]','Phòng STEM B305','12 Sư Vạn Hạnh, Quận 10, TP. Hồ Chí Minh','in_person',NULL,'THPT Nguyễn Trãi','Liên hệ THPT Nguyễn Trãi: c3-nguyentrai@hcm.edu.vn, 028-3863-1234','c3-nguyentrai@hcm.edu.vn','028-3863-1234','/app/learner/assets/activities/covers/nguyen-trai-python-robot.webp','Minh họa cho hoạt động Dự án Robot cứu hộ',0.00,'VND','Người học đang theo học tại THPT Nguyễn Trãi','Minh chứng tham gia trên TalentHub','2026-08-25 10:32:44.731024','2026-08-25 10:32:44.731024'),('21000000-8e2d-4dae-8d47-ea4ac11c3dc3','20000000-0000-4000-8000-000000000052','school_only','Kinh doanh','Kinh doanh','Phát triển ý tưởng kinh doanh từ nhu cầu thực tế của học sinh.','Các đội xây dựng mô hình giá trị, dự toán cơ bản và thuyết trình trước hội đồng phản biện.','[\"Xác định vấn đề\", \"Lập mô hình kinh doanh\", \"Pitching ý tưởng\"]','[\"Khởi nghiệp\", \"Tài chính cơ bản\", \"Thuyết trình\"]','[\"Đang theo học tại THPT Nguyễn Trãi\", \"Đăng ký trước thời hạn của hoạt động\"]','[\"Xác nhận giờ trải nghiệm sau check-in\", \"Minh chứng tham gia trên TalentHub\"]','Hội trường B','12 Sư Vạn Hạnh, Quận 10, TP. Hồ Chí Minh','in_person',NULL,'THPT Nguyễn Trãi','Liên hệ THPT Nguyễn Trãi: c3-nguyentrai@hcm.edu.vn, 028-3863-1234','c3-nguyentrai@hcm.edu.vn','028-3863-1234','/app/learner/assets/activities/covers/nguyen-trai-young-business.webp','Minh họa cho hoạt động Thử thách Doanh nhân trẻ',0.00,'VND','Người học đang theo học tại THPT Nguyễn Trãi','Minh chứng tham gia trên TalentHub','2026-08-25 10:32:44.731024','2026-08-25 10:32:44.731024'),('22000000-b817-48d3-8ab2-6b7dc54cd16e','22000000-dc34-49ed-81d4-78446b313553','school_only','Sáng tạo','Sáng tạo','Trình diễn sản phẩm âm nhạc do sinh viên phối hợp thực hiện.','Người tham gia chuẩn bị tiết mục, hoàn thiện kỹ năng sân khấu và chia sẻ quy trình sáng tạo.','[\"Chuẩn bị tiết mục\", \"Biểu diễn nhóm\", \"Chia sẻ hậu trường\"]','[\"Âm nhạc\", \"Biểu diễn\", \"Hợp tác\"]','[\"Đang theo học tại Đại học FPT\", \"Đăng ký trước thời hạn của hoạt động\"]','[\"Xác nhận giờ trải nghiệm sau check-in\", \"Minh chứng tham gia trên TalentHub\"]','Studio âm nhạc FPT','Khuôn viên Đại học FPT','in_person',NULL,'Đại học FPT','Liên hệ đơn vị tổ chức',NULL,NULL,'/app/learner/assets/activities/covers/fpt-music-showcase.webp','Minh họa cho hoạt động FPTU Music Studio Showcase',0.00,'VND','Người học đang theo học tại Đại học FPT','Minh chứng tham gia trên TalentHub','2026-08-25 10: