INSERT INTO `learner_ai_roadmaps` VALUES ('1475356c-6df3-46f9-8da2-211b6cac6d3a','1e5c4644-36e3-47c1-8d94-cb4aada7b006','436449d0-f3c3-4c54-a4f4-5cfaf53e8e22',1,'learner-roadmap-1.0.0','active','Lộ trình 90 ngày hỗ trợ phát triển kỹ năng toàn diện, kết hợp tư duy logic, tổ chức công việc và khả năng thực thi thực tế nhằm định hình định hướng học tập và dự án cá nhân rõ ràng.','{\"code\":\"project_management_operations\",\"label\":\"Quản trị Dự án và Vận hành Kỹ thuật\",\"rationale\":\"Sự kết hợp giữa tư duy cấu trúc, tinh thần trách nhiệm và khả năng định hướng hành động thực tiễn hỗ trợ tốt việc lập kế hoạch và điều phối hoạt động.\"}','[{\"code\":\"creative_technical_design\",\"label\":\"Thiết kế và Ứng dụng Không gian Kỹ thuật\",\"rationale\":\"Khả năng tư duy hình ảnh và ngôn ngữ trực quan tạo điều kiện thuận lợi cho việc chuyển đổi ý tưởng sáng tạo thành giải pháp thực tế.\"},{\"code\":\"business_communication_analytics\",\"label\":\"Phân tích và Truyền thông Kinh doanh\",\"rationale\":\"Thế mạnh về diễn đạt thông tin và suy luận logic giúp hỗ trợ xây dựng giải pháp và truyền tải kế hoạch một cách thuyết phục.\"}]','[{\"category\":\"strength\",\"title\":\"Tư duy tổ chức và định hướng mục tiêu\",\"summary\":\"Thể hiện khả năng tiếp cận công việc một cách rõ ràng, chú trọng kết quả và duy trì tính ổn định trong quá trình triển khai nhiệm vụ.\",\"evidence_ref_ids\":[\"evidence-002\",\"evidence-003\"]},{\"category\":\"potential\",\"title\":\"Khả năng phối hợp đa dạng giữa logic và ngôn ngữ\",\"summary\":\"Tiềm năng kết nối dữ liệu, cấu trúc thông điệp và hình dung không gian giúp xử lý các vấn đề tổng hợp một cách linh hoạt.\",\"evidence_ref_ids\":[\"evidence-004\"]},{\"category\":\"improvement\",\"title\":\"Cân bằng giữa thực thi thực tế và nghiên cứu lý thuyết\",\"summary\":\"Cần tăng cường thói quen phân tích sâu trước khi thực thi để nâng cao tính bền vững cho các phương án xử lý công việc.\",\"evidence_ref_ids\":[\"evidence-001\"]}]','high','{\"assessment_count\":4,\"skill_count\":0,\"activity_count\":0,\"evaluation_count\":0}','chatcmpl-nmGMasDhKZqm1e8P_8GXiQk','d04b2e8fb9b68eae697950e6f950aef1541b0e543326ec1b4016b2e671e1ed55','2026-08-24 15:21:04.000000',NULL,'2026-08-24 15:21:04.000000'),('ddb253e5-0589-4863-99cd-af68dc2ad2fb','b3eb7c9c-f886-4cda-9bc0-f2e93e4085b4','ecbd6362-9218-4688-b21d-01693938dc6e',1,'learner-roadmap-1.0.0','active','Lộ trình 90 ngày được thiết kế nhằm hỗ trợ bạn phát triển toàn diện dựa trên thế mạnh hành động thực tế, tư duy logic và khả năng sáng tạo. Kế hoạch tập trung từng bước giúp bạn khám phá định hướng, rèn luyện kỹ năng giải quyết vấn đề và xây dựng sản phẩm cá nhân một cách có hệ thống.','{\"code\":\"project_management_design\",\"label\":\"Quản lý Dự án & Thiết kế Ứng dụng\",\"rationale\":\"Sự kết hợp giữa tư duy tổ chức thực tế, khả năng phân tích logic và thiên hướng sáng tạo giúp bạn tiếp cận hiệu quả các vai trò điều phối, tối ưu hóa quy trình và thiết kế giải pháp.\"}','[{\"code\":\"tech_operations\",\"label\":\"Vận hành Kỹ thuật & Tối ưu Quy trình\",\"rationale\":\"Phù hợp với xu hướng chú trọng tính thực tiễn, tính kỷ luật và sự kiên trì trong việc chuẩn hóa các hệ thống vận hành.\"},{\"code\":\"creative_communication\",\"label\":\"Sáng tạo Nội dung & Truyền thông Đa phương tiện\",\"rationale\":\"Khai thác thế mạnh về ngôn ngữ, khả năng truyền đạt rõ ràng kết hợp cùng tư duy hình ảnh không gian trực quan.\"}]','[{\"category\":\"strength\",\"title\":\"Năng lực hành động và tư duy tổ chức vững vàng\",\"summary\":\"Bạn thể hiện sự chủ động, quyết đoán trong việc chuyển ý tưởng thành hành động thực tế và duy trì tính trật tự trong công việc.\",\"evidence_ref_ids\":[\"evidence-001\",\"evidence-002\",\"evidence-003\"]},{\"category\":\"potential\",\"title\":\"Khả năng phân tích ngôn ngữ và không gian đa chiều\",\"summary\":\"Nền tảng tư duy logic kết hợp nhận thức không gian và ngôn ngữ tạo tiềm năng tốt cho việc xây dựng giải pháp có tính cấu trúc cao.\",\"evidence_ref_ids\":[\"evidence-004\"]},{\"category\":\"improvement\",\"title\":\"Cân bằng giữa tốc độ thực thi và sự linh hoạt sáng tạo\",\"summary\":\"Việc cởi mở tiếp nhận các góc nhìn mới và kiên nhẫn lắng nghe sẽ giúp quá trình cộng tác và điều chỉnh giải pháp đạt hiệu quả cao hơn.\",\"evidence_ref_ids\":[\"evidence-002\",\"evidence-003\"]}]','high','{\"assessment_count\":4,\"skill_count\":0,\"activity_count\":0,\"evaluation_count\":0}','chatcmpl-LWaMavrQMfK1juMP-ouQ2AI','a7c15898bf6a3ab86fb71f21708cfae767764cd36cc97b834c8d2d05d9908881','2026-08-24 15:40:29.000000',NULL,'2026-08-24 15:40:29.000000');
