DROP TABLE IF EXISTS `learner_recommendation_runs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `learner_recommendation_runs` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `studentId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `snapshotId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `idempotencyKey` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `engineType` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `ruleVersion` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `provider` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `modelVersion` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `promptVersion` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fallbackReason` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `safeErrorCode` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `startedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `completedAt` datetime(6) DEFAULT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_learner_recommendation_runs_student_idempotency` (`studentId`,`idempotencyKey`),
  UNIQUE KEY `uq_learner_recommendation_runs_id_student` (`id`,`studentId`),
  KEY `idx_learner_recommendation_runs_student_created` (`studentId`,`createdAt`),
  KEY `idx_learner_recommendation_runs_snapshot_student` (`snapshotId`,`studentId`),
  CONSTRAINT `fk_learner_recommendation_runs_snapshot_owner` FOREIGN KEY (`snapshotId`, `studentId`) REFERENCES `learner_recommendation_input_snapshots` (`id`, `studentId`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_learner_recommendation_runs_student` FOREIGN KEY (`studentId`) REFERENCES `student_profiles` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_learner_recommendation_runs_completion` CHECK ((((`status` = _utf8mb4'pending') and (`completedAt` is null)) or ((`status` in (_utf8mb4'completed',_utf8mb4'failed',_utf8mb4'fallback')) and (`completedAt` is not null)))),
  CONSTRAINT `chk_learner_recommendation_runs_engine` CHECK ((`engineType` in (_utf8mb4'rule',_utf8mb4'model'))),
  CONSTRAINT `chk_learner_recommendation_runs_engine_versions` CHECK ((((`engineType` = _utf8mb4'rule') and (`ruleVersion` is not null) and (`provider` is null) and (`modelVersion` is null) and (`promptVersion` is null)) or ((`engineType` = _utf8mb4'model') and (`ruleVersion` is null) and (`provider` is not null) and (`modelVersion` is not null) and (`promptVersion` is not null)))),
  CONSTRAINT `chk_learner_recommendation_runs_status` CHECK ((`status` in (_utf8mb4'pending',_utf8mb4'completed',_utf8mb4'failed',_utf8mb4'fallback')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
