DROP TABLE IF EXISTS `payment_orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payment_orders` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `enterpriseId` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sponsorshipId` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `currency` char(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'VND',
  `provider` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `paymentStatus` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `providerReference` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `paidAt` datetime(6) DEFAULT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updatedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_payment_sponsorship` (`sponsorshipId`),
  KEY `idx_payment_enterprise_status` (`enterpriseId`,`paymentStatus`),
  CONSTRAINT `fk_payment_enterprise` FOREIGN KEY (`enterpriseId`) REFERENCES `enterprises` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_payment_sponsorship` FOREIGN KEY (`sponsorshipId`) REFERENCES `project_sponsorships` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_payment_amount` CHECK ((`amount` > 0)),
  CONSTRAINT `chk_payment_status` CHECK ((`paymentStatus` in (_utf8mb4'pending',_utf8mb4'paid',_utf8mb4'failed',_utf8mb4'cancelled',_utf8mb4'refunded')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
