INSERT INTO `test_questions` VALUES ('000f16a0-be60-4ae1-a8f7-8d7083378340','63e59ff9-1a95-4673-98f0-70397ee70dd9','disc_high_c_024','Bạn sắp xếp thời gian học theo kế hoạch rõ ràng.','[{\"value\":1,\"label\":\"Hoàn toàn không đồng ý\"},{\"value\":2,\"label\":\"Không đồng ý\"},{\"value\":3,\"label\":\"Bình thường\"},{\"value\":4,\"label\":\"Đồng ý\"},{\"value\":5,\"label\":\"Hoàn toàn đồng ý\"}]','published','2026-08-20 06:14:41.623865','2026-08-20 06:14:41.623865'),('00f6154a-c330-420a-adae-06c3c1057e22','e9eda43a-b649-4976-92d6-4ee38668b8b3','disc_middle_c_008','Bạn làm bài theo các bước đã được hướng dẫn.','[{\"value\":1,\"label\":\"Hoàn toàn không đồng ý\"},{\"value\":2,\"label\":\"Không đồng ý\"},{\"value\":3,\"label\":\"Bình thường\"},{\"value\":4,\"label\":\"Đồng ý\"},{\"value\":5,\"label\":\"Hoàn toàn đồng ý\"}]','published','2026-08-20 06:14:41.573276','2026-08-20 06:14:41.573276'),('01a0394a-e9da-4f0c-71df-909835556e92','13cd8227-2e1d-4b6a-985f-dd98ca68fee5','mbti_college_tf_f_030','Bạn coi trọng sự thấu cảm khi hợp tác học thuật.','[{\"value\":1,\"label\":\"Hoàn toàn không đồng ý\"},{\"value\":2,\"label\":\"Không đồng ý\"},{\"value\":3,\"label\":\"Bình thường\"},{\"value\":4,\"label\":\"Đồng ý\"},{\"value\":5,\"label\":\"Hoàn toàn đồng ý\"}]','published','2026-08-20 06:14:41.532502','2026-08-20 06:14:41.532502'),('01f0806d-4c23-40db-a901-30d5902485f0','2864de93-6555-4b9c-b0f6-e8726e7dd805','holland_middle_a_003','Bạn thích vẽ, nặn đất sét hoặc làm đồ thủ công.','[{\"value\":1,\"label\":\"Hoàn toàn không đồng ý\"},{\"value\":2,\"label\":\"Không đồng ý\"},{\"value\":3,\"label\":\"Bình thường\"},{\"value\":4,\"label\":\"Đồng ý\"},{\"value\":5,\"label\":\"Hoàn toàn đồng ý\"}]','published','2026-08-20 06:14:41.348138','2026-08-20 06:14:41.348138'),('027c0e96-4b83-4e11-82f8-5de23d832331','c401f1c9-bd87-41f4-91aa-854143c4bdf6','multiple_intelligence_high_body_020','Bạn thích tự làm thử khi học một kỹ năng mới.','[{\"value\":1,\"label\":\"Hoàn toàn không đồng ý\"